record.field:
if records:
    # Get the first record (in case multiple are selected)
    task = records[0]

    if task.project_id:
        # Open the project in form view
        action = {
            'type': 'ir.actions.act_window',
            'res_model': 'project.project',
            'res_id': task.project_id.id,
            'view_mode': 'form',
            'target': 'current',
            'name': task.project_id.name,
        }
    else:
        # Show warning if no project is linked
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'No Project',
                'message': 'This task is not linked to any project.',
                'type': 'warning',
                'sticky': False,
            }
        }
elif context.get('active_model') == 'project.project' and context.get('active_id'):
    # Try to get project from context
    project = env['project.project'].browse(context['active_id'])
    if project.exists():
        action = {
            'type': 'ir.actions.act_window',
            'res_model': 'project.project',
            'res_id': project.id,
            'view_mode': 'form',
            'target': 'current',
            'name': project.name,
        }
else:
    raise UserError(_("No tasks selected and no parent project found."))
